// Массив с данными о книгах
const books = [
  { title: "Мастер и Маргарита", author: "Булгаков", year: 1967 },
  { title: "Маленький принц", author: "Сент-Экзюпери", year: 1943 },
  { title: "Гордость и предубеждение", author: "Остин", year: 1813 }
];

// Переменная для счётчика
let totalBooks = 0;

// Объект-результат
const result = {
  student: "Subotkovskaya",
  topic: "lab4/Subotkovskaya/code",
  booksCount: 0,
  booksList: []
};

// Цикл for — проходим по всем книгам
for (let i = 0; i < books.length; i++) {
  const book = books[i];
  totalBooks++;

  // if/else — проверяем год
  if (book.year > 1900) {
    result.booksList.push(book.title + " (современная)");
  } else {
    result.booksList.push(book.title + " (классика)");
  }
}

// Записываем итоговое количество
result.booksCount = totalBooks;

// Возвращаем объект с полем payload
return [{ json: { payload: result } }];
